from pathlib import Path
D=Path('/mnt/data/legal_site')

def shell(title, active, content):
    nav=[('dashboard.html','▣','Dashboard'),('cases.html','▤','My Cases'),('clients.html','♙','Clients'),('appointments.html','◫','Appointments'),('messages.html','✉','Messages'),('documents.html','▧','Documents'),('profile.html','◉','Profile'),('settings.html','⚙','Settings')]
    links=''.join(f'<a class="{"active" if active==p else ""}" href="{p}"><i class="ico">{i}</i><span>{n}</span></a>' for p,i,n in nav)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | The Legal Choice Portal</title><link rel="stylesheet" href="portal.css"></head><body onload="protectPortal()"><div class="portal"><aside class="side"><a class="portal-brand" href="dashboard.html"><img src="assets/logo.png" alt="Logo"><div><strong>The Legal Choice</strong><small>JUSTICE · TRUST · SUPPORT</small></div></a><div class="user-mini"><img class="avatar" src="https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=100&q=80"><div><strong>Adv. Safi ur Rehman</strong><span>● Online · Lawyer</span></div></div><div class="navtitle">Main Menu</div>{links}<div class="navtitle">Account</div><a href="index.html"><i class="ico">⌂</i><span>Public Website</span></a><a href="#" onclick="portalLogout();return false"><i class="ico">↪</i><span>Logout</span></a></aside><main class="main"><header class="topbar"><div class="search">⌕ <input placeholder="Search cases, clients, appointments..."></div><div class="top-actions"><span class="bell">♧<b>3</b></span><a class="top-user" href="profile.html"><img src="https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=100&q=80"><div><strong>Haroon Ibn Rasheed</strong><br><span class="muted">Lawyer</span></div></a></div></header><div class="content">{content}</div></main></div><div class="mobilebar"><a class="btn" href="dashboard.html">Dashboard</a><a class="btn gold" href="portal-login.html" onclick="portalLogout()">Logout</a></div><script src="portal.js"></script></body></html>'''

def write(name,title,active,content): (D/name).write_text(shell(title,active,content),encoding='utf-8')

